diff --git a/segment.go b/segment.go
index c38244b..d24815d 100644
--- a/segment.go
+++ b/segment.go
@@ -634,6 +634,12 @@ func loadBasicSegment(sloc *SegmentLoc) (Segment, error) {
 		if sloc.KvsBytes > uint64(len(sloc.mref.buf)) {
 			return nil, fmt.Errorf("store: load basic segment KvsOffset/KvsBytes too big,"+
 				" len(mref.buf): %d, sloc: %+v", len(sloc.mref.buf), sloc)
+
+		if sloc.KvsBytes%8 != 0 {
+			return nil, fmt.Errorf("store: load basic segment KvsBytes not divisible by 8,"+
+				" KvsBytes: %d, sloc: %+v", sloc.KvsBytes, sloc)
+		}
+
 		}

 		kvsBytes := sloc.mref.buf[0:sloc.KvsBytes]

